# ---- the censuses — every literal MEASURED before it was typed (scratchpad g1_census.py); each assert a tripwire ----
# THE CREATION CHAPTER
c_vayomer = [k[2] for k in CRE if 'ויאמר' in toks(*k)];                       assert c_vayomer == [3, 6, 9, 11, 14, 20, 24, 26, 28, 29], c_vayomer   # TEN 'and God said' (the tradition counts nine + 'in the beginning')
c_vayhi_khen = [k[2] for k in CRE if has('ויהי', 'כן')(toks(*k))];             assert c_vayhi_khen == [7, 9, 11, 15, 24, 30], c_vayhi_khen
c_ki_tov = [k[2] for k in CRE if 'טוב' in toks(*k)];                            assert c_ki_tov == [4, 10, 12, 18, 21, 25, 31], c_ki_tov            # seven; NONE on the second day (1:6-8)
c_tov_by_day = {1: [4], 2: [], 3: [10, 12], 4: [18], 5: [21], 6: [25, 31]}
DAY_RANGES = {1: (1, 5), 2: (6, 8), 3: (9, 13), 4: (14, 19), 5: (20, 23), 6: (24, 31)}
assert all(sorted(v for v in c_ki_tov if DAY_RANGES[d][0] <= v <= DAY_RANGES[d][1]) == c_tov_by_day[d] for d in DAY_RANGES), 'the good-by-day census moved'
c_eve_morn = [k[2] for k in G(1, 1, 31) if has('ויהי', 'ערב', 'ויהי', 'בקר')(toks(*k))];   assert c_eve_morn == [5, 8, 13, 19, 23, 31], c_eve_morn
assert not any(has('ויהי', 'ערב')(toks(*k)) for k in G(2, 1, 3)), 'the seventh day has no evening'
c_ordinals = [(5, 'אחד'), (8, 'שני'), (13, 'שלישי'), (19, 'רביעי'), (23, 'חמישי'), (31, 'הששי')]
assert all(w in toks('Gen', 1, v) for v, w in c_ordinals), c_ordinals
c_articled = [w for v, w in c_ordinals if w.startswith('ה')];                    assert c_articled == ['הששי'], c_articled                            # THE sixth alone articled (Shabbat 88a)
c_seventh = [(k[2], cnt(k, 'השביעי')) for k in G(2, 1, 3)];                     assert c_seventh == [(1, 0), (2, 2), (3, 1)], c_seventh
c_hashishi_torah = torah('הששי');                                                assert c_hashishi_torah == [('Exod', 16, 5), ('Exod', 16, 22), ('Exod', 16, 29), ('Gen', 1, 31), ('Num', 7, 42), ('Num', 29, 29)], c_hashishi_torah
c_bless = [k[2] if k[1] == 1 else 100 + k[2] for k in CRE if 'ויברך' in toks(*k)];   assert c_bless == [22, 28, 103], c_bless    # the fish, the man, the seventh day
c_sanctify = [k for k in CRE if 'ויקדש' in toks(*k)];                            assert c_sanctify == [('Gen', 2, 3)], c_sanctify
c_lemino = [(k[2], [t for t in toks(*k) if t.startswith('למינ')]) for k in G(1, 1, 31) if any(t.startswith('למינ') for t in toks(*k))]
assert c_lemino == [(11, ['למינו']), (12, ['למינהו', 'למינהו']), (21, ['למינהם', 'למינהו']), (24, ['למינה', 'למינה']), (25, ['למינה', 'למינה', 'למינהו'])], c_lemino
c_lemino_n = sum(len(x[1]) for x in c_lemino);                                   assert c_lemino_n == 10, c_lemino_n
c_finished = (toks('Gen', 2, 1)[0], toks('Gen', 2, 2)[0]);                       assert c_finished == ('ויכלו', 'ויכל'), c_finished
c_melakhto = [cnt(k, 'מלאכתו') for k in G(2, 1, 3)];                             assert c_melakhto == [0, 2, 1], c_melakhto
c_bereshit = tanakh('בראשית');                                                   assert c_bereshit == [('Gen', 1, 1), ('Jer', 26, 1), ('Jer', 27, 1), ('Jer', 28, 1), ('Jer', 49, 34)], c_bereshit
c_bara = sum(cnt(k, 'ברא') + cnt(k, 'ויברא') for k in CRE);                       assert c_bara == 6, c_bara                                           # 1:1, 1:21, 1:27 x3, 2:3
c_asah = sum(sum(1 for t in toks(*k) if t in ('עשה', 'ויעש', 'נעשה', 'לעשות')) for k in CRE);   assert c_asah == 10, c_asah
c_image_26 = [t for t in toks('Gen', 1, 26) if 'צלמ' in t or 'דמות' in t];      assert c_image_26 == ['בצלמנו', 'כדמותנו'], c_image_26
c_image_27 = [t for t in toks('Gen', 1, 27) if 'צלמ' in t or 'צלם' in t];                       assert c_image_27 == ['בצלמו', 'בצלם'], c_image_27               # the likeness DROPPED at the run
c_betzelem = tanakh_any('בצלם', 'בצלמו', 'בצלמנו');                               assert c_betzelem == [('Gen', 1, 26), ('Gen', 1, 27), ('Gen', 9, 6), ('Ps', 39, 7)], c_betzelem
c_zn = tanakh_phrase(['זכר', 'ונקבה']);                                          assert c_zn == [('Gen', 1, 27), ('Gen', 5, 2), ('Gen', 6, 19), ('Gen', 7, 3), ('Gen', 7, 9), ('Gen', 7, 16)], c_zn
c_them_27 = cnt(('Gen', 1, 27), 'אתם') + cnt(('Gen', 1, 27), 'אתו');             assert c_them_27 == 2, c_them_27                                     # 'created HIM'... 'created THEM'
c_them_28 = cnt(('Gen', 1, 28), 'אתם') + cnt(('Gen', 1, 28), 'להם');             assert c_them_28 == 2, c_them_28                                     # 'blessed THEM... said to THEM'
c_subdue = [t for t in toks('Gen', 1, 28) if t.startswith('וכבש')];               assert c_subdue == ['וכבשה'], c_subdue                             # DEFECTIVE — read 'subdue HER' (Yevamot 65b)
c_subdue_homograph = tanakh('וכבשה');                                            assert c_subdue_homograph == [('Gen', 1, 28), ('Lev', 14, 10), ('Num', 6, 14)], c_subdue_homograph   # the EWE at the other two
c_rule = [(k[2], [t for t in toks(*k) if t in ('ורדו', 'וירדו')]) for k in G(1, 26, 28) if any(t in ('ורדו', 'וירדו') for t in toks(*k))];   assert c_rule == [(26, ['וירדו']), (28, ['ורדו'])], c_rule
c_tree = ([w for w in toks('Gen', 1, 11) if w in ('עץ', 'פרי', 'עשה')], [w for w in toks('Gen', 1, 12) if w in ('ועץ', 'עץ', 'פרי', 'עשה')])
assert c_tree == (['עץ', 'פרי', 'עשה', 'פרי'], ['ועץ', 'עשה', 'פרי']), c_tree     # 'FRUIT tree making fruit' -> 'tree making fruit'
c_lights = ([w for w in toks('Gen', 1, 16) if w in ('שני', 'הגדלים')], [w for w in toks('Gen', 1, 16) if w in ('הגדל', 'הקטן')]);   assert c_lights == (['שני', 'הגדלים'], ['הגדל', 'הקטן']), c_lights
c_beasts_order = ([w for w in toks('Gen', 1, 24) if w in ('בהמה', 'ורמש', 'וחיתו')], [w for w in toks('Gen', 1, 25) if w in ('חית', 'הבהמה', 'רמש')])
assert c_beasts_order == (['בהמה', 'ורמש', 'וחיתו'], ['חית', 'הבהמה', 'רמש']), c_beasts_order   # the order SWAPPED between spec and run
c_waters_run = toks('Gen', 1, 9)[-2:];                                           assert c_waters_run == ['ויהי', 'כן'], c_waters_run                 # the one command executed by 'and it was so' alone
c_taninim = [t for t in toks('Gen', 1, 21) if 'תנינ' in t];                       assert c_taninim == ['התנינם'], c_taninim                           # defective
c_nefesh_chayah = tanakh_phrase(['נפש', 'חיה']);                                  assert c_nefesh_chayah == [('Ezek', 47, 9), ('Gen', 1, 20), ('Gen', 1, 24), ('Gen', 1, 30), ('Gen', 2, 19), ('Gen', 9, 12), ('Gen', 9, 15), ('Gen', 9, 16)], c_nefesh_chayah
c_moed_span = [(k, [t for t in toks(*k) if 'מועד' in t]) for k in SPAN if any('מועד' in t for t in toks(*k))];   assert c_moed_span == [(('Gen', 1, 14), ['ולמועדים']), (('Gen', 17, 21), ['למועד'])], c_moed_span
OPENERS = [(1, 1, 'בראשית'), (1, 6, 'יהי'), (1, 9, 'יקוו'), (1, 14, 'יהי'), (1, 20, 'ישרצו'), (1, 24, 'תוצא'), (2, 1, 'ויכלו')]
assert all(w in toks('Gen', c, v)[:3] for c, v, w in OPENERS), OPENERS          # the maamad's seven section names = the chapter's opening tokens
PARAS = [(1, 1, 5), (1, 6, 8), (1, 9, 13), (1, 14, 19), (1, 20, 23), (1, 24, 31), (2, 1, 3)]
c_para_sizes = [z - a + 1 for c, a, z in PARAS];                                 assert c_para_sizes == [5, 3, 5, 6, 4, 8, 3], c_para_sizes
c_elohim_n = sum(cnt(k, 'אלהים') for k in CRE);                                  assert c_elohim_n == 35, c_elohim_n
c_yehi_or = toks('Gen', 1, 3)[2:];                                               assert c_yehi_or == ['יהי', 'אור', 'ויהי', 'אור'], c_yehi_or          # the spec and its run in one verse, token for token
# THE SABBATH'S THREE SEATS
c_shabbat_gen = [(k[2], [t for t in toks(*k) if 'שבת' in t]) for k in G(2, 1, 3) if any('שבת' in t for t in toks(*k))];   assert c_shabbat_gen == [(2, ['וישבת']), (3, ['שבת'])], c_shabbat_gen
c_noun_first = [k for k in tanakh_any('שבת', 'השבת', 'שבתון') if k[0] in ('Gen', 'Exod')][:4];   assert c_noun_first == [('Exod', 16, 23), ('Exod', 16, 25), ('Exod', 16, 26), ('Exod', 16, 29)], c_noun_first   # the NOUN first at the manna; Genesis has the verb only
c_vayinafash = tanakh('וינפש');                                                  assert c_vayinafash == [('2Sam', 16, 14), ('Exod', 23, 12), ('Exod', 31, 17)], c_vayinafash
c_vayanach_exod = [k for k in tanakh('וינח') if k[0] == 'Exod'];                  assert c_vayanach_exod == [('Exod', 10, 14), ('Exod', 20, 11)], c_vayanach_exod
c_rest_verbs = ([t for t in toks('Gen', 2, 2) + toks('Gen', 2, 3) if 'שבת' in t], [t for t in toks('Exod', 20, 11) if t in ('וינח', 'שבת')], [t for t in toks('Exod', 31, 17) if t in ('שבת', 'וינפש')], [t for t in toks('Exod', 23, 12) if t in ('תשבת', 'ינוח', 'וינפש')])
assert c_rest_verbs == (['וישבת', 'שבת'], ['וינח'], ['שבת', 'וינפש'], ['תשבת', 'ינוח', 'וינפש']), c_rest_verbs
c_bless_seats = ([t for t in toks('Gen', 2, 3) if t.startswith('ויברך') or t.startswith('ויקדש')], [t for t in toks('Exod', 20, 11) if t.startswith('ברך') or t.startswith('ויקדש')], [t for t in toks('Exod', 31, 17) if t.startswith('ברך') or t.startswith('ויקדש')])
assert c_bless_seats == (['ויברך', 'ויקדש'], ['ברך', 'ויקדשהו'], []), c_bless_seats   # the sign seat drops the blessing and the sanctification
c_vayqadesh_oto = tanakh_phrase(['ויקדש', 'אתו']);                                assert c_vayqadesh_oto == [('Gen', 2, 3), ('Num', 7, 1)], c_vayqadesh_oto   # the seventh day and the tabernacle
c_vayqadeshehu = tanakh('ויקדשהו');                                              assert c_vayqadeshehu == [('Exod', 20, 11), ('Lev', 8, 15)], c_vayqadeshehu   # the Sabbath day and the altar
c_six_days = [k for k in tanakh_phrase(['כי', 'ששת', 'ימים', 'עשה']) if k[0] == 'Exod'];   assert c_six_days == [('Exod', 20, 11), ('Exod', 31, 17)], c_six_days
# THE FIRST COMMAND AND THE UNIONS' ROOT
c_2_16 = toks('Gen', 2, 16);                                                     assert c_2_16 == ['ויצו', 'יהוה', 'אלהים', 'על', 'האדם', 'לאמר', 'מכל', 'עץ', 'הגן', 'אכל', 'תאכל'], c_2_16
c_2_24 = toks('Gen', 2, 24);                                                     assert c_2_24 == ['על', 'כן', 'יעזב', 'איש', 'את', 'אביו', 'ואת', 'אמו', 'ודבק', 'באשתו', 'והיו', 'לבשר', 'אחד'], c_2_24
c_vaytzav_first = [k for k in tanakh('ויצו') if k[0] == 'Gen'][:3];              assert c_vaytzav_first == [('Gen', 2, 16), ('Gen', 12, 20), ('Gen', 26, 11)], c_vaytzav_first   # the command verb's first seat
c_jer_3_1 = toks('Jer', 3, 1)[:6];                                               assert c_jer_3_1 == ['לאמר', 'הן', 'ישלח', 'איש', 'את', 'אשתו'], c_jer_3_1   # 'SAYING' — the unions' proof-text opens with the token
c_18_19 = 'יצוה' in toks('Gen', 18, 19);                                         assert c_18_19, 'the courts leg: he will COMMAND his children'
c_3_3_added = [t for t in toks('Gen', 3, 3) if t in ('ולא', 'תגעו', 'בו')];      assert c_3_3_added == ['ולא', 'תגעו', 'בו'], c_3_3_added           # the retelling ADDS 'nor touch it' (Sanhedrin 29a: whoever adds subtracts)
c_2_17_death = toks('Gen', 2, 17)[-2:];                                          assert c_2_17_death == ['מות', 'תמות'], c_2_17_death
c_3_3_death = toks('Gen', 3, 3)[-2:];                                            assert c_3_3_death == ['פן', 'תמתון'], c_3_3_death                  # 'you shall surely die' retold 'lest you die'
# THE NOAHIDE CODE
c_head_shared = (toks('Gen', 1, 28)[6:11], toks('Gen', 9, 1)[8:13]);            assert c_head_shared == (['פרו', 'ורבו', 'ומלאו', 'את', 'הארץ'],) * 2, c_head_shared   # the blessing's five tokens at both seats
c_9_1_drops = [t for t in toks('Gen', 1, 28) if t in ('וכבשה', 'ורדו') and t not in toks('Gen', 9, 1)];   assert c_9_1_drops == ['וכבשה', 'ורדו'], c_9_1_drops   # Noah's blessing drops subdue and rule; 9:2 gives fear instead
c_fear = toks('Gen', 9, 2)[:2];                                                  assert c_fear == ['ומוראכם', 'וחתכם'], c_fear
c_9_3 = toks('Gen', 9, 3);                                                       assert c_9_3 == ['כל', 'רמש', 'אשר', 'הוא', 'חי', 'לכם', 'יהיה', 'לאכלה', 'כירק', 'עשב', 'נתתי', 'לכם', 'את', 'כל'], c_9_3
c_1_29_grant = toks('Gen', 1, 29)[3:7];                                          assert c_1_29_grant == ['נתתי', 'לכם', 'את', 'כל'], c_1_29_grant   # 'I have given you all' — the same four tokens at 9:3's tail
c_9_3_grant = toks('Gen', 9, 3)[10:14];                                          assert c_9_3_grant == ['נתתי', 'לכם', 'את', 'כל'], c_9_3_grant
c_9_4 = toks('Gen', 9, 4);                                                       assert c_9_4 == ['אך', 'בשר', 'בנפשו', 'דמו', 'לא', 'תאכלו'], c_9_4
c_benafsho_torah = torah('בנפשו');                                               assert c_benafsho_torah == [('Gen', 9, 4), ('Gen', 44, 30), ('Lev', 17, 14)], c_benafsho_torah   # Judah's 'his soul bound with his soul' the third
c_life_blood_pair = (has('בנפשו', 'דמו')(toks('Gen', 9, 4)), has('דמו', 'בנפשו')(toks('Lev', 17, 14)));   assert c_life_blood_pair == (True, True), c_life_blood_pair   # the two tokens SWAPPED between the seats
c_9_5 = toks('Gen', 9, 5);                                                       assert c_9_5 == ['ואך', 'את', 'דמכם', 'לנפשתיכם', 'אדרש', 'מיד', 'כל', 'חיה', 'אדרשנו', 'ומיד', 'האדם', 'מיד', 'איש', 'אחיו', 'אדרש', 'את', 'נפש', 'האדם'], c_9_5
c_require = [t for t in c_9_5 if t.startswith('אדרש')];                          assert c_require == ['אדרש', 'אדרשנו', 'אדרש'], c_require            # three require-verbs
c_hands = [t for t in c_9_5 if t in ('מיד', 'ומיד')];                             assert c_hands == ['מיד', 'ומיד', 'מיד'], c_hands                     # three hand-tokens (57b:4's four legs with 'his brother')
c_9_6 = toks('Gen', 9, 6);                                                       assert c_9_6 == ['שפך', 'דם', 'האדם', 'באדם', 'דמו', 'ישפך', 'כי', 'בצלם', 'אלהים', 'עשה', 'את', 'האדם'], c_9_6
c_chiasm = (c_9_6[0], c_9_6[5], c_9_6[1], c_9_6[4], c_9_6[2], c_9_6[3]);        assert c_chiasm == ('שפך', 'ישפך', 'דם', 'דמו', 'האדם', 'באדם'), c_chiasm   # sheds/shed, blood/his blood, man/in man
c_shofekh_tanakh = len(tanakh('שפך'));                                           assert c_shofekh_tanakh == 19, c_shofekh_tanakh                    # 'sheds' at nineteen seats, Gen 9:6 the first
c_yishafekh_lev4 = [k for k in tanakh('ישפך') if k[0] == 'Lev'];                 assert c_yishafekh_lev4 == [('Lev', 4, 7), ('Lev', 4, 18), ('Lev', 4, 25), ('Lev', 4, 30), ('Lev', 4, 34)], c_yishafekh_lev4   # the homograph: 'shall be SHED' / 'he shall POUR' one string
c_21_12 = MP_21_12;                                                              assert c_21_12 == ['מכה', 'איש', 'ומת', 'מות', 'יומת'], c_21_12       # the murder law's Sinai seat, fetched
c_24_17 = toks('Lev', 24, 17);                                                   assert c_24_17 == ['ואיש', 'כי', 'יכה', 'כל', 'נפש', 'אדם', 'מות', 'יומת'], c_24_17
c_ish_ish_24_15 = has('איש', 'איש')(toks('Lev', 24, 15));                         assert c_ish_ish_24_15, 'the blasphemy leg: ANY MAN (Lev 24:15)'
c_9_7 = toks('Gen', 9, 7);                                                       assert c_9_7 == ['ואתם', 'פרו', 'ורבו', 'שרצו', 'בארץ', 'ורבו', 'בה'], c_9_7
c_multiply_twice = cnt(('Gen', 9, 7), 'ורבו');                                   assert c_multiply_twice == 2, c_multiply_twice
c_sheretzu = tanakh('שרצו');                                                     assert c_sheretzu == [('Gen', 1, 21), ('Gen', 9, 7)], c_sheretzu     # 'swarmed' (the waters) and 'swarm!' (Noah) — the castration leg's token
c_brit_9 = [(k[2], sum(1 for t in toks(*k) if t in ('בריתי', 'ברית', 'הברית'))) for k in NOAH if any(t in ('בריתי', 'ברית', 'הברית') for t in toks(*k))];   assert c_brit_9 == [(9, 1), (11, 1), (12, 1), (13, 1), (15, 1), (16, 1), (17, 1)], c_brit_9
c_qeshet = [(k[2], [t for t in toks(*k) if 'קשת' in t]) for k in NOAH if any('קשת' in t for t in toks(*k))];   assert c_qeshet == [(13, ['קשתי']), (14, ['הקשת']), (16, ['הקשת'])], c_qeshet
c_od = [(k[2], cnt(k, 'עוד')) for k in NOAH if 'עוד' in toks(*k)];                assert c_od == [(11, 2), (15, 1)], c_od                              # 'no more' DOUBLED at 9:11 — the oath (Shevuot 36a)
c_ledorot = [t for t in toks('Gen', 9, 12) if 'דר' in t];                         assert c_ledorot == ['לדרת'], c_ledorot                             # defective: no vav
c_ledorot_forms = (tanakh('לדרת'), tanakh('לדרות'), tanakh('לדורות'));             assert c_ledorot_forms == ([('Gen', 9, 12)], [], []), c_ledorot_forms
c_remember_covenant = tanakh_phrase(['וזכרתי', 'את', 'בריתי']);                   assert c_remember_covenant == [('Gen', 9, 15), ('Lev', 26, 42)], c_remember_covenant   # the two seats of one clause
c_brit_olam = len(tanakh_phrase(['ברית', 'עולם']));                              assert c_brit_olam == 12, c_brit_olam
c_mabul_gen = [k for k in tanakh_any('מבול', 'המבול') if k[0] == 'Gen'];          assert len(c_mabul_gen) == 9 and ('Gen', 9, 11) in c_mabul_gen, c_mabul_gen
c_isa_swore = cnt(('Isa', 54, 9), 'נשבעתי');                                     assert c_isa_swore == 2, c_isa_swore                                 # 'as I have SWORN' — twice
c_karet_first = [k for k in tanakh('ונכרתה') if k[0] == 'Gen'];                   assert c_karet_first == [('Gen', 17, 14), ('Gen', 26, 28)], c_karet_first   # 17:14 the Torah's first karet; 26:28 'let us CUT a covenant' — one string
c_karet_n = len(tanakh('ונכרתה'));                                               assert c_karet_n == 18, c_karet_n
c_lev26_42 = toks('Lev', 26, 42)[:3];                                            assert c_lev26_42 == ['וזכרתי', 'את', 'בריתי'], c_lev26_42
# CIRCUMCISION
c_brit_17 = [(k[2], sum(1 for t in toks(*k) if t in ('ברית', 'בריתי', 'הברית', 'לברית'))) for k in ABR if any(t in ('ברית', 'בריתי', 'הברית', 'לברית') for t in toks(*k))]
assert c_brit_17 == [(2, 1), (4, 1), (7, 2), (9, 1), (10, 1), (11, 1), (13, 2), (14, 1), (19, 2), (21, 1)], c_brit_17
c_brit_17_n = sum(n for _, n in c_brit_17);                                      assert c_brit_17_n == 13, c_brit_17_n                                # NEDARIM 3:11's thirteen
MUL = ('המול', 'ונמלתם', 'ימול', 'וימל', 'בהמלו', 'נמול', 'נמלו')
c_mul = [(k[2], [t for t in toks(*k) if t in MUL]) for k in ABR if any(t in MUL for t in toks(*k))]
assert c_mul == [(10, ['המול']), (11, ['ונמלתם']), (12, ['ימול']), (13, ['המול', 'ימול']), (14, ['ימול']), (23, ['וימל']), (24, ['בהמלו']), (25, ['בהמלו']), (26, ['נמול']), (27, ['נמלו'])], c_mul
