# ---- the alignment engine (E2/E5's), reused on the creation chapter's command/execution pairs and the three rest seats ----
def norm(w):
    w = re.sub(r'^ו', '', w); w = re.sub(r'^[הלכב]', '', w) if len(w) > 3 else w
    return w
def bagt(ws): return collections.Counter(norm(w) for w in ws)
def jact(a, b):
    A, B = bagt(a), bagt(b); i = sum((A & B).values()); u = sum((A | B).values()); return round(i / u, 2) if u else 0
def delta(spec, run):
    A, B = bagt(spec), bagt(run); return (sorted((B - A).elements()), sorted((A - B).elements()))
T = toks
A_LIGHT = jact(T('Gen', 1, 3)[2:4], T('Gen', 1, 3)[4:6])
A_PLANTS = delta(T('Gen', 1, 11)[2:-2], T('Gen', 1, 12)[:-4])
A_MAN = delta(T('Gen', 1, 26)[2:], T('Gen', 1, 27))
A_REST_20 = delta(T('Gen', 2, 2) + T('Gen', 2, 3), T('Exod', 20, 11))
A_REST_31 = delta(T('Exod', 20, 11), T('Exod', 31, 17))
A_BLESS_9 = delta(T('Gen', 1, 28), T('Gen', 9, 1))
A_GRANT = delta(T('Gen', 1, 29), T('Gen', 9, 3))
A_RETOLD = delta(T('Gen', 2, 16) + T('Gen', 2, 17), T('Gen', 3, 2) + T('Gen', 3, 3))
A_17_RUN = max(((jact(T('Gen', 17, s), T('Gen', 17, 27)), s) for s in range(9, 15)))
print('alignment: light j=%.2f; plants %s; man %s; the rest clause at three seats diffed; the blessing and the grant at two; the first command against its retelling' % (A_LIGHT, A_PLANTS[0], A_MAN[1][:3]))

