# ---- F7: THE SCENE — the creation week, the covenant, and the house of Abraham on the world engine --------------------
import world_engine as WE
def law_pre_sinai(event, world):
    """The pre-Sinai daemon: consumes the span's recorded acts and writes the ledger — never emits an event."""
    k, subj, src = event['kind'], event['subject'], event['case_source']
    day = world.clock.day
    E_ = lambda eff, s, due=None, cp=None, value=None: {'effect': eff, 'subject': s, 'counterparty': cp, 'amount': None, 'due': due, 'value': value if value is not None else True, 'source_law': 'F%s' % event.get('law', '7'), 'case_source': src}
    if k == 'evening_and_morning': return [E_('day_counted', 'the-world', value=event['day'])]
    if k == 'ceased_and_blessed': return [E_('seventh_day_blessed', 'the-seventh-day')]
    if k == 'blessed_be_fruitful': return [E_('fruitfulness_blessed', subj)] + ([E_('dominion_granted', subj)] if event.get('rule') else [])
    if k == 'fear_set': return [E_('fear_on_beasts', 'the-beasts')]
    if k == 'meat_granted': return [E_('meat_permitted', subj), E_('dominion_granted', subj)]
    if k == 'limb_barred': return [E_('limb_from_living_barred', subj)]
    if k == 'blood_required': return [E_('blood_required', subj)]
    if k == 'flood_sworn_off': return [E_('flood_barred', 'the-earth'), E_('covenant_cut', 'the-earth')]
    if k == 'bow_set': return [E_('bow_set', 'the-cloud')]
    if k == 'walk_commanded': return [E_('wholeness_owed', subj)]
    if k == 'renamed': return [E_('name_changed', subj)]
    if k == 'circumcision_commanded': return [E_('circumcision_due', s) for s in event['males']]
    if k == 'circumcised': return [E_('sign_in_the_flesh', subj)]
    if k == 'born': return [E_('circumcision_due', subj, due=day + 8)]           # the eighth day: a per-person TIMER from the birth (17:12; 21:4 the first run)
    return []

def scene():
    with contextlib.redirect_stdout(io.StringIO()):
        w = WE.World(era='the creation week into the covenants (clock unit: days; the tape\'s own order)')
        w.laws = [law_pre_sinai]
        for d, v in ((1, 5), (2, 8), (3, 13), (4, 19), (5, 23), (6, 31)):
            w.advance(d)
            w.submit({'kind': 'evening_and_morning', 'subject': 'the-world', 'day': d, 'case_source': 'Gen 1:%d' % v})
        w.advance(7)
        w.submit({'kind': 'ceased_and_blessed', 'subject': 'the-seventh-day', 'case_source': 'Gen 2:2-3'})
        w.submit({'kind': 'blessed_be_fruitful', 'subject': 'adam', 'rule': True, 'case_source': 'Gen 1:28'})
        w.advance(8)
        w.submit({'kind': 'blessed_be_fruitful', 'subject': 'noah', 'case_source': 'Gen 9:1'})
        w.submit({'kind': 'fear_set', 'subject': 'the-beasts', 'case_source': 'Gen 9:2'})
        w.submit({'kind': 'meat_granted', 'subject': 'noah', 'case_source': 'Gen 9:3'})
        w.submit({'kind': 'limb_barred', 'subject': 'noah', 'case_source': 'Gen 9:4'})
        w.submit({'kind': 'blood_required', 'subject': 'noah', 'case_source': 'Gen 9:5'})
        w.submit({'kind': 'blessed_be_fruitful', 'subject': 'noah', 'case_source': 'Gen 9:7'})
        w.submit({'kind': 'flood_sworn_off', 'subject': 'the-earth', 'case_source': 'Gen 9:11'})
        w.submit({'kind': 'bow_set', 'subject': 'the-cloud', 'case_source': 'Gen 9:13'})
        w.advance(9)
        w.submit({'kind': 'walk_commanded', 'subject': 'abraham', 'case_source': 'Gen 17:1'})
        w.submit({'kind': 'renamed', 'subject': 'abraham', 'case_source': 'Gen 17:5'})
        w.submit({'kind': 'circumcision_commanded', 'subject': 'abraham', 'males': ['abraham', 'ishmael', 'the-household'], 'case_source': 'Gen 17:10-13'})
        w.submit({'kind': 'renamed', 'subject': 'sarah', 'case_source': 'Gen 17:15'})
        for s, src in (('abraham', 'Gen 17:24'), ('ishmael', 'Gen 17:25'), ('the-household', 'Gen 17:23, 17:27')):
            w.submit({'kind': 'circumcised', 'subject': s, 'case_source': src})
            w.close(s, 'circumcision_due', src)
        w.close('abraham', 'wholeness_owed', 'Gen 17:24 (Nedarim 31b:11: whole when he circumcised)')
        w.advance(10)
        w.submit({'kind': 'born', 'subject': 'isaac', 'case_source': 'Gen 21:2'})     # the timer set: due day 18
        w.advance(18)                                                                    # the eighth day: the timer FIRES (21:4's run)
        w.submit({'kind': 'circumcised', 'subject': 'isaac', 'case_source': 'Gen 21:4'})
        w.close('isaac', 'circumcision_due', 'Gen 21:4')
    n = lambda eid, eff: len([e for e in w.entity(eid).ledger if e['effect'] == eff])
    op = lambda eid, eff: len([e for e in w.entity(eid).ledger if e['effect'] == eff and e.get('open')])
    fired = len([l for l in w.log if l[0] == 'TIMER-FIRE'])
    return (n('the-world', 'day_counted'), w.entity('the-world').status.get('day_counted'), n('the-seventh-day', 'seventh_day_blessed'),
            n('adam', 'fruitfulness_blessed'), n('noah', 'fruitfulness_blessed'), n('adam', 'dominion_granted') + n('noah', 'dominion_granted'), n('the-beasts', 'fear_on_beasts'),
            n('noah', 'meat_permitted'), n('noah', 'limb_from_living_barred'), n('noah', 'blood_required'), op('noah', 'blood_required'), n('the-earth', 'flood_barred'), n('the-cloud', 'bow_set'),
            n('abraham', 'wholeness_owed'), op('abraham', 'wholeness_owed'), n('abraham', 'name_changed') + n('sarah', 'name_changed'),
            n('abraham', 'circumcision_due') + n('ishmael', 'circumcision_due') + n('the-household', 'circumcision_due') + n('isaac', 'circumcision_due'),
            op('abraham', 'circumcision_due') + op('ishmael', 'circumcision_due') + op('the-household', 'circumcision_due') + op('isaac', 'circumcision_due'),
            n('abraham', 'sign_in_the_flesh') + n('ishmael', 'sign_in_the_flesh') + n('the-household', 'sign_in_the_flesh') + n('isaac', 'sign_in_the_flesh'), fired, w.clock.day)
SCENE = scene()

